        var playerBase = embedUrl.split("/video/")[0];
        var pageOrigin = (originOf(pageUrl) || S.base) + "/";
        var playerHeaders = {
            "User-Agent": S.ua,
            "Referer": playerBase + "/",
            "Origin": playerBase,
            "X-Requested-With": "XMLHttpRequest",
        };
